package com.arteon.geocam; import java.util.*; /** 사진 시각과 결과 시각의 정확한 대응만 확인한다. HDR 적용 여부는 판정하지 않는다. */ public final class CaptureEvidenceLink { private String id=""; private long imageTime=-1; private boolean blocked=false,closed=false; private final Map<Long,Set<Long>> frames=new HashMap<>(); public synchronized void begin(String captureId){if(captureId==null||captureId.isEmpty())throw new IllegalArgumentException("captureId");id=captureId;imageTime=-1;blocked=false;closed=false;frames.clear();} private boolean accepts(String captureId){return !closed&&!id.isEmpty()&&id.equals(captureId);} public synchronized void image(String captureId,long timestamp){if(!accepts(captureId))return;if(timestamp<=0){blocked=true;return;}if(imageTime>0&&imageTime!=timestamp){blocked=true;return;}imageTime=timestamp;} public synchronized void result(String captureId,long timestamp,long frameNumber){if(!accepts(captureId))return;if(timestamp<=0||frameNumber<0){blocked=true;return;}Set<Long> group=frames.get(timestamp);if(group!=null&&group.contains(frameNumber))return;int total=0;for(Set<Long> g:frames.values())total+=g.size();if(total>=8){blocked=true;return;}if(group==null){group=new HashSet<>();frames.put(timestamp,group);}group.add(frameNumber);} public synchronized String status(String captureId){if(!id.equals(captureId)||id.isEmpty())return "STALE_CAPTURE";if(closed)return "CLOSED_UNVERIFIED";if(blocked)return "INVALID_OR_OVERFLOW";if(imageTime<=0)return "WAITING_IMAGE";Set<Long> group=frames.get(imageTime);if(group==null)return frames.isEmpty()?"WAITING_RESULT":"TIMESTAMP_MISMATCH";return group.size()==1?"TIMESTAMP_MATCHED":"AMBIGUOUS_RESULT";} public synchronized void cancel(String captureId){if(id.equals(captureId)){closed=true;frames.clear();}} }